          { "id": "electrolyte-imbalances-100-0", "q": "What is hyponatremia?", "a": "Serum sodium <135 mEq/L — sodium dilution in total body water", "rationale": "Hyponatremia occurs with water excess, sodium loss, or in SIADH; can be symptomatic (confusion, seizures) or asymptomatic depending on speed of onset." },
          { "id": "electrolyte-imbalances-100-1", "q": "What is hypernatremia?", "a": "Serum sodium >145 mEq/L — relative water deficit", "rationale": "Hypernatremia occurs from free water loss, poor intake, or excessive sodium intake; causes thirst, altered mental status, seizures in severe cases." },
          { "id": "electrolyte-imbalances-100-2", "q": "What is hypokalemia?", "a": "Serum potassium <3.5 mEq/L — a critical electrolyte affecting muscle and cardiac function", "rationale": "Hypokalemia causes weakness, cardiac dysrhythmias (flattened T waves, U waves), and polyuria; common with diuretics, diarrhea, or renal tubular acidosis." },
          { "id": "electrolyte-imbalances-100-3", "q": "What is hyperkalemia?", "a": "Serum potassium >5.0 mEq/L — dangerous risk for cardiac dysrhythmias and arrest", "rationale": "Hyperkalemia causes peaked T waves, widened QRS, and potentially fatal dysrhythmias; caused by renal failure, cell lysis, or excessive supplementation." },
          { "id": "electrolyte-imbalances-100-4", "q": "What is hypocalcemia?", "a": "Total serum calcium <8.5 mg/dL (or ionized Ca <4.0 mg/dL) — causes neuromuscular excitability", "rationale": "Hypocalcemia presents with paresthesias, tetany (involuntary muscle contractions), and Chvostek's sign; caused by vitamin D deficiency, hypoparathyroidism, or hyperphosphatemia." },
          { "id": "electrolyte-imbalances-100-5", "q": "What is hypercalcemia?", "a": "Total serum calcium >10.5 mg/dL — causes muscle weakness and altered mental status", "rationale": "Hypercalcemia (often from PTH or vitamin D excess) presents as 'stone, bone, stone and psychiatric overtones' — kidney stones, bone disease, depression." },
          { "id": "electrolyte-imbalances-100-6", "q": "What is hypomagnesemia?", "a": "Serum magnesium <1.7 mg/dL — can cause tetany, cardiac dysrhythmias, and worsen hypokalemia", "rationale": "Magnesium regulates muscle and nerve function; deficiency is common with diuretics, diarrhea, or PPI use; treat Mg before trying to correct K." },
          { "id": "electrolyte-imbalances-100-7", "q": "What is hypermagnesemia?", "a": "Serum magnesium >2.2 mg/dL — causes muscle weakness and hyporeflexia", "rationale": "Rare, usually from renal failure and excessive supplementation; presents with lethargy, weak reflexes, and can progress to respiratory paralysis." }
