          { "id": "perioperative-nursing-500-0", "q": "What is anaphylaxis during surgery, and how is it managed?", "a": "IgE-mediated reaction to anesthetics/antibiotics/blood products → urticaria, angioedema, hypotension, bronchospasm; emergency treatment: epinephrine IM, airway control, IV fluids", "rationale": "Most common cause: neuromuscular blocking agents; rapid recognition and epinephrine crucial; anesthesia must maintain vigilance; resuscitate per ACLS." },
          { "id": "perioperative-nursing-500-1", "q": "What is disseminated intravascular coagulation (DIC) in perioperative context?", "a": "Massive activation of clotting (consuming factors/platelets/fibrin) + fibrinolysis from tissue damage, sepsis, transfusion reaction → bleeding paradoxically", "rationale": "Occurs with major trauma, massive transfusion, amniotic fluid embolism; treated with fresh frozen plasma, cryoprecipitate, platelet transfusion; address underlying cause." },
          { "id": "perioperative-nursing-500-2", "q": "What is fat embolism syndrome (FES), and when does it occur?", "a": "Fat particles embolize to lungs/brain from orthopedic surgery (femur/tibia fracture repair) or major trauma → fat particles, thrombocytopenia, fever, rash, dyspnea, altered mental status", "rationale": "Occurs 12-72 hours post-op; symptoms: petechial rash on trunk, confusion, hypoxemia; treatment supportive; early stabilization of fractures reduces risk." },
          { "id": "perioperative-nursing-500-3", "q": "What is amniotic fluid embolism (AFE) during cesarean section?", "a": "Amniotic fluid enters maternal circulation (from uterine manipulation) → anaphylactic-like reaction, cardiovascular collapse, coagulopathy, death", "rationale": "Rare but catastrophic (60-80% mortality); immediate resuscitation: epinephrine, airway control, massive transfusion, DIC management; transport to ICU." },
          { "id": "perioperative-nursing-500-4", "q": "What is massive transfusion protocol (MTP) in trauma surgery?", "a": "Simultaneous transfusion of PRBCs, FFP, platelets in 1:1:1 ratio + aggressive crystalloid; used for ongoing hemorrhage/shock", "rationale": "Activates when large-volume hemorrhage/hypotension expected; prevents dilutional coagulopathy; frequent labs (CBC, PT/INR, fibrinogen) guide ongoing therapy." },
          { "id": "perioperative-nursing-500-5", "q": "What is perioperative optimization in high-risk surgery, and what does it include?", "a": "Preoperative assessment identifying modifiable risk factors (nutrition, anemia, glucose, cardiac/pulmonary function) + intraoperative monitoring + aggressive post-op care", "rationale": "Goal-directed fluid therapy (CVP/MAP/lactate targets), normothermia, glucose control, VTE prophylaxis, infection prevention reduce major complications." },
          { "id": "perioperative-nursing-500-6", "q": "What is postoperative cognitive dysfunction (POCD), and who is at risk?", "a": "Delirium/confusion lasting days-weeks post-op; risk factors: age >60, baseline cognitive impairment, major surgery, ICU stay, hypoxemia, infection, medications", "rationale": "Multifactorial (anesthesia, stress, infection, hypoxemia, pain, sleep deprivation); management: early mobilization, orientation, minimize sedatives, control pain/infection." },
          { "id": "perioperative-nursing-500-7", "q": "What is the role of patient-controlled analgesia (PCA) post-op, and what safety measures are needed?", "a": "Patient self-administers opioid within programmed limits (demand dose, lockout interval) → better pain control than fixed dosing; safety: monitoring for respiratory depression, naloxone at bedside", "rationale": "PCA improves satisfaction, reduces opioid consumption vs. traditional dosing; requires education pre-op; monitor respiratory rate, sedation level, O2 sat; never allow family dosing." }
